var e={kind:`board`,caption:`只读事务 R 读两次 name；中间事务 101、102 先后把 'A' 改成 'B'、'C' 并提交`,stepTitles:{0:`隐藏字段`,1:`修改时生成版本链`,2:`读时生成 Read View`,3:`判断可见性`,4:`沿版本链往回找`},cols:2,regions:[{id:`row`,label:`聚簇索引里的这一行（最新版本）`},{id:`undo`,label:`undo log 里的旧版本（新 → 旧）`},{id:`view`,label:`R 的读视图（Read View）`},{id:`trx`,label:`事务`}],legend:[[`new`,`刚写入`],[`bad`,`对 R 不可见`],[`ok`,`对 R 可见`],[`hit`,`进行中`]],frames:[{step:0,boxes:{row:{items:[{t:`name = 'A'`},{t:`DB_TRX_ID = 100`},{t:`DB_ROLL_PTR → NULL`}],hot:!0},undo:{items:[]},view:{items:[]},trx:{items:[{t:`100 已提交`,st:`dim`}]}},calc:[[`DB_TRX_ID`,`最后插入 / 修改这行的事务 id`],[`DB_ROLL_PTR`,`指向 undo log 里的上一个版本`]],note:`表 t 里有一行 name = 'A'，是事务 100 插入并已提交的。聚簇索引里的这行带着隐藏字段：DB_TRX_ID = 100，回滚指针 DB_ROLL_PTR 还是空的（没有更早的版本）。`},{step:1,boxes:{row:{items:[{t:`name = 'B'`,st:`new`},{t:`DB_TRX_ID = 101`,st:`new`},{t:`DB_ROLL_PTR → undo（'A'）`}],hot:!0},undo:{items:[{t:`'A'  trx=100`,st:`new`}],hot:!0},view:{items:[]},trx:{items:[{t:`101 未提交`,st:`hit`}]}},calc:[[`事务 101`,`UPDATE t SET name = 'B'`],[`顺序`,`加排他锁 → 旧内容写进 undo log → 改这一行`]],note:`事务 101 把 name 改成 'B'（还没提交）：先给这行加排他锁，把修改前的 'A' 写进 undo log，再改这一行 —— DB_TRX_ID 换成 101，回滚指针指向刚写的 undo 记录。版本链：B → A。`},{step:2,boxes:{row:{items:[{t:`name = 'B'`},{t:`DB_TRX_ID = 101`},{t:`DB_ROLL_PTR → undo（'A'）`}]},undo:{items:[{t:`'A'  trx=100`}]},view:{items:[{t:`m_ids = [101]`},{t:`min_trx_id = 101`},{t:`max_trx_id = 102`},{t:`creator_trx_id = 0`}],hot:!0},trx:{items:[{t:`101 未提交`,st:`hit`},{t:`R 只读，第一次 SELECT`,st:`new`}]}},calc:[[`m_ids`,`这一刻还没提交的读写事务：101`],[`max_trx_id`,`下一个将要分配的事务 id：102`],[`creator_trx_id`,`R 没写过数据，没分配事务 id，记 0`]],note:`只读事务 R（可重复读）执行第一次普通 SELECT，生成读视图。可重复读下，这个读视图会一直用到 R 结束。`},{step:3,boxes:{row:{items:[{t:`name = 'B'`,st:`bad`},{t:`DB_TRX_ID = 101`,st:`bad`},{t:`DB_ROLL_PTR → undo（'A'）`}],hot:!0},undo:{items:[{t:`'A'  trx=100`}]},view:{items:[{t:`m_ids = [101]`},{t:`min_trx_id = 101`},{t:`max_trx_id = 102`},{t:`creator_trx_id = 0`}]},trx:{items:[{t:`101 未提交`,st:`hit`},{t:`R 读取中`,st:`hit`}]}},calc:[[`当前看的版本`,`'B'（DB_TRX_ID = 101）`],[`判断`,`101 在 m_ids [101] 里，还没提交 → 不可见`]],note:`先看行上的当前版本 'B'：它的 DB_TRX_ID 是 101，在 m_ids 里 —— 事务 101 生成读视图时还没提交，所以 R 看不见 'B'。`},{step:4,boxes:{row:{items:[{t:`name = 'B'`,st:`bad`},{t:`DB_TRX_ID = 101`,st:`bad`},{t:`DB_ROLL_PTR → undo（'A'）`}]},undo:{items:[{t:`'A'  trx=100`,st:`ok`}],hot:!0},view:{items:[{t:`m_ids = [101]`},{t:`min_trx_id = 101`},{t:`max_trx_id = 102`},{t:`creator_trx_id = 0`}]},trx:{items:[{t:`101 未提交`,st:`hit`},{t:`R 读取中`,st:`hit`}]}},calc:[[`当前看的版本`,`'A'（DB_TRX_ID = 100）`],[`判断`,`100 < min_trx_id 101，读视图生成前已提交 → 可见`],[`读到`,`'A'`]],note:`顺着回滚指针到 undo log 取上一个版本 'A'：DB_TRX_ID 100 小于 min_trx_id 101，读视图生成前就提交了，可见。R 第一次读到 'A'。`},{step:1,boxes:{row:{items:[{t:`name = 'C'`,st:`new`},{t:`DB_TRX_ID = 102`,st:`new`},{t:`DB_ROLL_PTR → undo（'B'）`}],hot:!0},undo:{items:[{t:`'B'  trx=101`,st:`new`},{t:`'A'  trx=100`,st:null}],hot:!0},view:{items:[{t:`m_ids = [101]`},{t:`min_trx_id = 101`},{t:`max_trx_id = 102`},{t:`creator_trx_id = 0`}]},trx:{items:[{t:`101 已提交`,st:`dim`},{t:`102 已提交`,st:`dim`},{t:`R 还没结束`,st:null}]}},calc:[[`事务 101`,`提交`],[`事务 102`,`UPDATE … name = 'C'，提交`],[`版本链`,`C → B → A`]],note:`事务 101 提交了；接着事务 102 把 'B' 改成 'C' 并提交。又多了一个版本，链变成 C → B → A。R 的读视图没有变。`},{step:2,boxes:{row:{items:[{t:`name = 'C'`},{t:`DB_TRX_ID = 102`},{t:`DB_ROLL_PTR → undo（'B'）`}]},undo:{items:[{t:`'B'  trx=101`},{t:`'A'  trx=100`}]},view:{items:[{t:`m_ids = [101]`},{t:`min_trx_id = 101`},{t:`max_trx_id = 102`},{t:`creator_trx_id = 0`}],hot:!0},trx:{items:[{t:`R 第二次 SELECT`,st:`new`}]}},calc:[[`隔离级别`,`可重复读`],[`读视图`,`沿用第一次读时建的那个，不新建`]],note:`R 第二次 SELECT。可重复读只在事务里第一次快照读时建读视图，之后一直沿用 —— 所以还是 m_ids = [101]、max_trx_id = 102。`},{step:3,boxes:{row:{items:[{t:`name = 'C'`,st:`bad`},{t:`DB_TRX_ID = 102`,st:`bad`},{t:`DB_ROLL_PTR → undo（'B'）`}],hot:!0},undo:{items:[{t:`'B'  trx=101`},{t:`'A'  trx=100`}]},view:{items:[{t:`m_ids = [101]`},{t:`min_trx_id = 101`},{t:`max_trx_id = 102`},{t:`creator_trx_id = 0`}]},trx:{items:[{t:`R 读取中`,st:`hit`}]}},calc:[[`当前看的版本`,`'C'（DB_TRX_ID = 102）`],[`判断`,`102 ≥ max_trx_id 102，读视图生成后才开始 → 不可见`]],note:`当前版本 'C' 是事务 102 改的，102 ≥ max_trx_id 102：读视图生成之后才开始的事务，不可见。`},{step:4,boxes:{row:{items:[{t:`name = 'C'`,st:`bad`},{t:`DB_TRX_ID = 102`,st:`bad`},{t:`DB_ROLL_PTR → undo（'B'）`}]},undo:{items:[{t:`'B'  trx=101`,st:`bad`},{t:`'A'  trx=100`,st:null}],hot:!0},view:{items:[{t:`m_ids = [101]`},{t:`min_trx_id = 101`},{t:`max_trx_id = 102`},{t:`creator_trx_id = 0`}]},trx:{items:[{t:`R 读取中`,st:`hit`}]}},calc:[[`当前看的版本`,`'B'（DB_TRX_ID = 101）`],[`判断`,`101 在 m_ids [101] 里，还没提交 → 不可见`]],note:`往回找到 'B'：101 在读视图的 m_ids 里。虽然 101 现在已经提交了，但对这个读视图来说它当时还没提交，照样不可见。`},{step:4,boxes:{row:{items:[{t:`name = 'C'`,st:`bad`},{t:`DB_TRX_ID = 102`,st:`bad`},{t:`DB_ROLL_PTR → undo（'B'）`}]},undo:{items:[{t:`'B'  trx=101`,st:`bad`},{t:`'A'  trx=100`,st:`ok`}],hot:!0},view:{items:[{t:`m_ids = [101]`},{t:`min_trx_id = 101`},{t:`max_trx_id = 102`},{t:`creator_trx_id = 0`}]},trx:{items:[{t:`R 读取中`,st:`hit`}]}},calc:[[`当前看的版本`,`'A'（DB_TRX_ID = 100）`],[`判断`,`100 < min_trx_id 101，读视图生成前已提交 → 可见`],[`读到`,`'A'`]],note:`再往回到 'A'：100 < 101，可见。R 第二次还是读到 'A' —— 这就是可重复读。`},{step:2,boxes:{row:{items:[{t:`name = 'C'`,st:`ok`},{t:`DB_TRX_ID = 102`,st:`ok`},{t:`DB_ROLL_PTR → undo（'B'）`}],hot:!0},undo:{items:[{t:`'B'  trx=101`},{t:`'A'  trx=100`}]},view:{items:[{t:`m_ids = []`},{t:`min_trx_id = 103`},{t:`max_trx_id = 103`},{t:`creator_trx_id = 0`}],hot:!0},trx:{items:[{t:`如果是读已提交`,st:`new`}]}},calc:[[`读已提交`,`每条 SELECT 都新建读视图`],[`新读视图`,`m_ids 为空，min = max = 103`],[`判断 'C'（102）`,`102 < min_trx_id 103，读视图生成前已提交 → 可见`],[`读到`,`'C'`]],note:`对照：如果 R 是读已提交，第二次 SELECT 会新建读视图。这时 101、102 都已提交，m_ids 为空，'C' 直接可见，读到 'C'。同一个事务两次读到不同的值 —— 这就是不可重复读。演示结束。`}]};export{e as default};